def growth_counts(n):
    if n < 0:
        raise ValueError("n must be nonnegative")
    linear = 0
    pairs = 0
    halves = 0
    for _ in range(n):
        linear += 1
    for i in range(n):
        for _ in range(i + 1, n):
            pairs += 1
    remaining = n
    while remaining > 1:
        remaining //= 2
        halves += 1
    return linear, pairs, halves
